// Parse input data
// Supports:
// - Single text: { text: '...' }
// - Page segments: { segments: ['text1', 'text2'] }
// - Batch commentaries: { segments: [{commentary_id: '...', text: '...'}], commentator: 'Rashi' }
const input = $input.first().json;
const body = input.body || input;

const languageNames = {
  'fr': 'français',
  'en': 'English',
  'es': 'español',
  'he': 'hébreu',
  'ar': 'araméen',
  'de': 'allemand',
  'it': 'italien'
};

const sourceLanguage = body.source_language || 'he';
const targetLanguage = body.target_language || 'fr';
const needsPivot = sourceLanguage !== 'en' && targetLanguage !== 'en';

// Handle segments - array of strings or objects, or single text
let segments = [];
if (Array.isArray(body.segments)) {
  segments = body.segments;
} else if (body.text) {
  segments = [body.text];
}

// Merge top-level commentator into metadata
const metadata = {
  ...(body.metadata || {}),
  commentator: body.commentator || body.metadata?.commentator
};

return [{
  json: {
    jobId: body.job_id,
    traite: body.traite,
    page: body.page,
    jobType: body.job_type || 'unit_translation',
    mode: body.mode || 'standard',
    sourceLanguage: sourceLanguage,
    sourceLangName: languageNames[sourceLanguage] || sourceLanguage,
    targetLanguage: targetLanguage,
    targetLangName: languageNames[targetLanguage] || targetLanguage,
    needsPivot: needsPivot,
    apiKey: body.api_key,
    openaiApiKey: body.openai_api_key,
    segments: segments,
    segmentsCount: segments.length,
    context: body.context || {},
    metadata: metadata,
    requestId: body.request_id,
    startTime: Date.now()
  }
}];

// Get original data and prepare for loop
const prevData = $('Parse Input').first().json;
return [{ json: prevData }];

// Split segments into individual items
// Supports both formats:
// - Array of strings: ['text1', 'text2'] (page translation)
// - Array of objects: [{commentary_id: '...', text: '...'}] (batch commentaries)
const input = $input.first().json;

const items = input.segments.map((segment, index) => {
  // Handle both string and object formats
  const isObject = typeof segment === 'object' && segment !== null;
  const segmentText = isObject ? segment.text : segment;
  const commentaryId = isObject ? segment.commentary_id : null;
  const sourceTextId = isObject ? segment.source_text_id : null;

  return {
    json: {
      segmentIndex: index,
      segmentText: segmentText,
      commentaryId: commentaryId,
      sourceTextId: sourceTextId,
      totalSegments: input.segments.length,
      jobId: input.jobId,
      traite: input.traite,
      page: input.page,
      jobType: input.jobType,
      mode: input.mode,
      sourceLanguage: input.sourceLanguage,
      sourceLangName: input.sourceLangName,
      targetLanguage: input.targetLanguage,
      targetLangName: input.targetLangName,
      needsPivot: input.needsPivot,
      apiKey: input.apiKey,
      openaiApiKey: input.openaiApiKey,
      context: input.context,
      metadata: input.metadata,
      requestId: input.requestId,
      startTime: input.startTime,
      allTranslations: [],
      totalClaudeTokens: { input_tokens: 0, output_tokens: 0, total_tokens: 0 },
      totalGptTokens: { input_tokens: 0, output_tokens: 0, total_tokens: 0 }
    }
  };
});

return items;

// Extract English translation and prepare for step 2
const input = $input.first().json;
const prevData = $('Needs Pivot?').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let englishTranslation = '';
let step1Usage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
let error = null;

if (statusCode >= 400 || data.error) {
  error = data.error?.message || `HTTP ${statusCode}`;
} else if (data.content?.[0]?.text) {
  englishTranslation = data.content[0].text.trim();
  step1Usage = {
    input_tokens: data.usage?.input_tokens || 0,
    output_tokens: data.usage?.output_tokens || 0,
    total_tokens: (data.usage?.input_tokens || 0) + (data.usage?.output_tokens || 0)
  };
}

return [{
  json: {
    ...prevData,
    intermediateTranslation: englishTranslation,
    step1Usage: step1Usage,
    pivotError: error
  }
}];

// Extract final translation from pivot
const input = $input.first().json;
const prevData = $('Extract Step 1').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let claudeTranslation = '';
let step2Usage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

if (statusCode < 400 && data.content?.[0]?.text) {
  claudeTranslation = data.content[0].text.trim();
  step2Usage = {
    input_tokens: data.usage?.input_tokens || 0,
    output_tokens: data.usage?.output_tokens || 0,
    total_tokens: (data.usage?.input_tokens || 0) + (data.usage?.output_tokens || 0)
  };
}

// Combine Claude usage from both steps
const step1Usage = prevData.step1Usage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
const claudeUsage = {
  input_tokens: step1Usage.input_tokens + step2Usage.input_tokens,
  output_tokens: step1Usage.output_tokens + step2Usage.output_tokens,
  total_tokens: step1Usage.total_tokens + step2Usage.total_tokens
};

return [{
  json: {
    ...prevData,
    claudeTranslation: claudeTranslation,
    claudeUsage: claudeUsage,
    pivotUsed: true
  }
}];

// Extract direct translation
const input = $input.first().json;
const prevData = $('Needs Pivot?').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let claudeTranslation = '';
let claudeUsage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

if (statusCode < 400 && data.content?.[0]?.text) {
  claudeTranslation = data.content[0].text.trim();
  claudeUsage = {
    input_tokens: data.usage?.input_tokens || 0,
    output_tokens: data.usage?.output_tokens || 0,
    total_tokens: (data.usage?.input_tokens || 0) + (data.usage?.output_tokens || 0)
  };
}

return [{
  json: {
    ...prevData,
    claudeTranslation: claudeTranslation,
    claudeUsage: claudeUsage,
    intermediateTranslation: null,
    pivotUsed: false
  }
}];

// Extract GPT verification
const input = $input.first().json;
const prevData = $('Merge Translations').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let verification = {
  my_translation: null,
  approved: true,
  confidence: 0.8,
  issues: [],
  notes: null
};
let gptUsage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

if (statusCode < 400 && data.choices?.[0]?.message?.content) {
  try {
    verification = JSON.parse(data.choices[0].message.content);
    gptUsage = {
      input_tokens: data.usage?.prompt_tokens || 0,
      output_tokens: data.usage?.completion_tokens || 0,
      total_tokens: (data.usage?.prompt_tokens || 0) + (data.usage?.completion_tokens || 0)
    };
  } catch (e) {
    // Keep defaults
  }
}

// Determine final translation
const finalTranslation = verification.approved ? prevData.claudeTranslation : (verification.my_translation || prevData.claudeTranslation);
const requiresVote = verification.confidence < 0.9 && !verification.approved;

return [{
  json: {
    ...prevData,
    verification: verification,
    gptUsage: gptUsage,
    finalTranslation: finalTranslation,
    confidence: verification.confidence || 0.8,
    approved: verification.approved,
    requiresVote: requiresVote,
    gptTranslation: verification.my_translation
  }
}];

// Prepare job update with detailed tokens
const input = $input.first().json;
const prevData = $('Extract GPT').first().json;

const segmentIndex = prevData.segmentIndex;
const totalSegments = prevData.totalSegments;
const isComplete = segmentIndex + 1 >= totalSegments;

const claudeUsage = prevData.claudeUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
const gptUsage = prevData.gptUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

const tokens = {
  claude: {
    input_tokens: claudeUsage.input_tokens,
    output_tokens: claudeUsage.output_tokens,
    total_tokens: claudeUsage.total_tokens
  },
  gpt: {
    input_tokens: gptUsage.input_tokens,
    output_tokens: gptUsage.output_tokens,
    total_tokens: gptUsage.total_tokens
  },
  total: {
    input_tokens: claudeUsage.input_tokens + gptUsage.input_tokens,
    output_tokens: claudeUsage.output_tokens + gptUsage.output_tokens,
    total_tokens: claudeUsage.total_tokens + gptUsage.total_tokens
  }
};

// Build translation result for this segment
const segmentResult = {
  segment_index: segmentIndex,
  original: prevData.segmentText,
  translation: prevData.finalTranslation,
  intermediate_en: prevData.intermediateTranslation,
  pivot_used: prevData.pivotUsed,
  confidence: prevData.confidence,
  approved: prevData.approved,
  requires_vote: prevData.requiresVote,
  claude_translation: prevData.claudeTranslation,
  gpt_translation: prevData.gptTranslation
};

return [{
  json: {
    ...prevData,
    isComplete: isComplete,
    segmentResult: segmentResult,
    tokens: tokens,
    updatePayload: isComplete ? {
      status: 'completed',
      translations_saved: segmentIndex + 1,
      tokens: tokens
    } : {
      status: 'in_progress',
      current_segment: segmentIndex + 1,
      translations_saved: segmentIndex + 1,
      tokens: tokens
    }
  }
}];

// Prepare result for external storage
const input = $input.first().json;
const prevData = $('Prepare Update').first().json;

// Use workflow static data to accumulate results across segments
const staticData = $getWorkflowStaticData('global');
const jobId = prevData.jobId;

if (!staticData.pendingResults) {
  staticData.pendingResults = {};
}
if (!staticData.pendingResults[jobId]) {
  staticData.pendingResults[jobId] = {
    segments: [],
    totalClaudeTokens: { input_tokens: 0, output_tokens: 0, total_tokens: 0 },
    totalGptTokens: { input_tokens: 0, output_tokens: 0, total_tokens: 0 }
  };
}

// Add this segment's result
staticData.pendingResults[jobId].segments.push(prevData.segmentResult);

// Accumulate tokens
const claudeUsage = prevData.claudeUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
const gptUsage = prevData.gptUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

staticData.pendingResults[jobId].totalClaudeTokens.input_tokens += claudeUsage.input_tokens;
staticData.pendingResults[jobId].totalClaudeTokens.output_tokens += claudeUsage.output_tokens;
staticData.pendingResults[jobId].totalClaudeTokens.total_tokens += claudeUsage.total_tokens;

staticData.pendingResults[jobId].totalGptTokens.input_tokens += gptUsage.input_tokens;
staticData.pendingResults[jobId].totalGptTokens.output_tokens += gptUsage.output_tokens;
staticData.pendingResults[jobId].totalGptTokens.total_tokens += gptUsage.total_tokens;

// Store metadata
staticData.pendingResults[jobId].jobId = jobId;
staticData.pendingResults[jobId].traite = prevData.traite;
staticData.pendingResults[jobId].page = prevData.page;
staticData.pendingResults[jobId].sourceLanguage = prevData.sourceLanguage;
staticData.pendingResults[jobId].targetLanguage = prevData.targetLanguage;
staticData.pendingResults[jobId].pivotUsed = prevData.pivotUsed;
staticData.pendingResults[jobId].startTime = prevData.startTime;
staticData.pendingResults[jobId].completedAt = prevData.isComplete ? Date.now() : null;

// Pass data along with the accumulated result for final storage
return [{ 
  json: {
    ...prevData,
    accumulatedResult: staticData.pendingResults[jobId]
  }
}];

// Get the final accumulated result and prepare for storage
const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;

// Find the jobId from previous data
let jobId = null;
let result = null;

// Get all pending results and find the completed one
if (staticData.pendingResults) {
  for (const [id, data] of Object.entries(staticData.pendingResults)) {
    if (data.completedAt) {
      jobId = id;
      result = data;
      // Clean up
      delete staticData.pendingResults[id];
      break;
    }
  }
}

if (!jobId || !result) {
  return [{ json: { stored: false, reason: 'no_completed_result' } }];
}

return [{
  json: {
    job_id: jobId,
    result: result
  }
}];
